/* Experiment 13: Check strings generated by S->aS | Sb | ab.
   This grammar generates one or more a's followed by one or more b's. */
#include <stdio.h>
#include <string.h>

int main(void) {
    char input[256];
    int i = 0, seen_b = 0, valid = 1;
    printf("Grammar: S->aS | Sb | ab\nEnter the string: ");
    if (scanf("%255s", input) != 1) return 1;

    if (input[0] != 'a') valid = 0;
    for (i = 0; input[i] && valid; i++) {
        if (input[i] == 'a' && !seen_b) continue;
        if (input[i] == 'b') seen_b = 1;
        else valid = 0;
    }
    if (!seen_b) valid = 0;
    puts(valid ? "String accepted" : "String not accepted");
    return 0;
}
